 [StructLayout(LayoutKind.Explicit,Size=32)] public struct UNION{[FieldOffset(0)]public MOUSEINPUT mouse;[FieldOffset(0)]public KEYBDINPUT key;}
 [StructLayout(LayoutKind.Sequential)] public struct INPUT{public uint type;public UNION data;}
 [DllImport("user32.dll",SetLastError=true)] static extern uint SendInput(uint n,INPUT[] e,int size);
 [DllImport("user32.dll")] static extern int GetSystemMetrics(int n);
 [DllImport("user32.dll")] static extern bool GetPhysicalCursorPos(out POINT p);
 [DllImport("user32.dll")] static extern IntPtr SetThreadDpiAwarenessContext(IntPtr context);
 [DllImport("user32.dll")] static extern IntPtr GetForegroundWindow();
 [DllImport("user32.dll")] static extern bool SetForegroundWindow(IntPtr h);
 [DllImport("user32.dll")] static extern IntPtr WindowFromPoint(POINT p);
 [DllImport("user32.dll")] static extern IntPtr GetAncestor(IntPtr h,uint flag);
 [DllImport("user32.dll",CharSet=CharSet.Unicode)] static extern int GetWindowText(IntPtr h,System.Text.StringBuilder text,int max);
 [DllImport("user32.dll")] static extern uint GetWindowThreadProcessId(IntPtr h,out uint pid);
 public struct RectData{public double x,y,width,height;}
 public sealed class GuardData{public RectData frame,target;public string id,name;public long windowHandle,foregroundHandle;public int desktopWidth,desktopHeight;public bool enabled,offscreen;}
 static RectData Rect(System.Windows.Rect r){return new RectData{x=r.X,y=r.Y,width=r.Width,height=r.Height};}
 public static GuardData InspectButton(string path,bool source,string id,string name){var dpi=SetThreadDpiAwarenessContext(new IntPtr(-4));try{var w=Window(path,source);AutomationElement target=null;foreach(AutomationElement e in w.FindAll(TreeScope.Descendants,Condition.TrueCondition)){if(e.Current.ControlType!=ControlType.Button)continue;if(source?e.Current.Name==name:e.Current.AutomationId==id){if(target!=null)throw new InvalidOperationException("Unique inspection button required");target=e;}}if(target==null)throw new InvalidOperationException("Inspection target absent");return new GuardData{frame=Rect(w.Current.BoundingRectangle),target=Rect(target.Current.BoundingRectangle),id=target.Current.AutomationId,name=target.Current.Name,windowHandle=w.Current.NativeWindowHandle,foregroundHandle=GetForegroundWindow().ToInt64(),desktopWidth=GetSystemMetrics(78),desktopHeight=GetSystemMetrics(79),enabled=target.Current.IsEnabled,offscreen=target.Current.IsOffscreen};}finally{if(dpi!=IntPtr.Zero)SetThreadDpiAwarenessContext(dpi);}}
 public sealed class HitData{public int x,y;public uint windowProcess;public long hitWindow;public string uiaType,uiaId,uiaName,uiaError;public int uiaProcess;}
 public static HitData InspectHit(string path,string id,string name){var dpi=SetThreadDpiAwarenessContext(new IntPtr(-4));try{var guard=InspectButton(path,false,id,name);var window=Window(path,false);int x=(int)Math.Round(guard.target.x+guard.target.width/2),y=(int)Math.Round(guard.target.y+guard.target.height/2);uint pid;var hit=WindowFromPoint(new POINT{x=x,y=y});GetWindowThreadProcessId(hit,out pid);var value=new HitData{x=x,y=y,windowProcess=pid,hitWindow=hit.ToInt64()};try{var element=AutomationElement.FromPoint(new System.Windows.Point(x,y));if(element!=null){value.uiaType=element.Current.ControlType.ProgrammaticName;value.uiaId=element.Current.AutomationId;value.uiaName=element.Current.Name;value.uiaProcess=element.Current.ProcessId;}}catch(Exception error){value.uiaError=error.ToString();}return value;}finally{if(dpi!=IntPtr.Zero)SetThreadDpiAwarenessContext(dpi);}}
 public static void Capture(string path,bool source,string output){var dpi=SetThreadDpiAwarenessContext(new IntPtr(-4));try{var w=Window(path,source);SetForegroundWindow(new IntPtr(w.Current.NativeWindowHandle));System.Threading.Thread.Sleep(100);if(GetForegroundWindow().ToInt64()!=w.Current.NativeWindowHandle)throw new InvalidOperationException("Owned capture foreground guard");var b=w.Current.BoundingRectangle;if(b.Width<500||b.Width>5000||b.Height<500||b.Height>3000)throw new InvalidOperationException("Owned capture frame guard");using(var bitmap=new System.Drawing.Bitmap((int)b.Width,(int)b.Height)){using(var graphics=System.Drawing.Graphics.FromImage(bitmap)){graphics.CopyFromScreen((int)b.Left,(int)b.Top,0,0,bitmap.Size);}bitmap.Save(output,System.Drawing.Imaging.ImageFormat.Png);}}finally{if(dpi!=IntPtr.Zero)SetThreadDpiAwarenessContext(dpi);}}
 static void Emit(INPUT e){if(SendInput(1,new[]{e},Marshal.SizeOf<INPUT>())!=1)throw new InvalidOperationException("Owned SendInput failed");}
 static void Move(int x,int y){int l=GetSystemMetrics(76),t=GetSystemMetrics(77),w=GetSystemMetrics(78),h=GetSystemMetrics(79);if(w<=1||h<=1||x<l||y<t||x>=l+w||y>=t+h)throw new InvalidOperationException("Display guard");Emit(new INPUT{data=new UNION{mouse=new MOUSEINPUT{dx=(int)Math.Round((x-l)*65535d/(w-1)),dy=(int)Math.Round((y-t)*65535d/(h-1)),flags=0x8000|0x4000|1}}});}
 static void Mouse(bool down){Emit(new INPUT{data=new UNION{mouse=new MOUSEINPUT{flags=down?2u:4u}}});}
 static void Key(ushort code){bool down=false;try{Emit(new INPUT{type=1,data=new UNION{key=new KEYBDINPUT{vk=code}}});down=true;System.Threading.Thread.Sleep(80);}finally{if(down)Emit(new INPUT{type=1,data=new UNION{key=new KEYBDINPUT{vk=code,flags=2}}});}}
 public static void Run(string path,bool source,string target,string mode,string expectedID,string expectedName){var priorDpi=SetThreadDpiAwarenessContext(new IntPtr(-4));try{LastStage="start";RunAware(path,source,target,mode,expectedID,expectedName);}catch(Exception error){throw new InvalidOperationException("Owned input diagnostic stage "+LastStage,error);}finally{if(priorDpi!=IntPtr.Zero)SetThreadDpiAwarenessContext(priorDpi);}}
 public static AutomationElement Window(string path,bool source){
  var temp=System.IO.Path.GetFullPath(Environment.GetEnvironmentVariable("TEMP"));var actual=System.IO.Path.GetFullPath(path);if(!actual.StartsWith(temp+System.IO.Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)||!System.Text.RegularExpressions.Regex.IsMatch(actual.Substring(temp.Length+1),@"^DBMV-Isolated-connection-pageintegration-[0-9a-f]{32}\\app\\ReplicaProbe\.exe$"))throw new InvalidOperationException("Fixed runtime guard");
  AutomationElement window=null;foreach(AutomationElement w in AutomationElement.RootElement.FindAll(TreeScope.Children,Condition.TrueCondition)){try{var name=w.Current.Name;if(source?!name.StartsWith("Results integration actual · original isolation"):name!="Replica PageIntegration application verification")continue;var process=System.Diagnostics.Process.GetProcessById(w.Current.ProcessId).MainModule.FileName;bool match=source?process.EndsWith(@"Microsoft\Edge\Application\msedge.exe",StringComparison.OrdinalIgnoreCase):string.Equals(process,path,StringComparison.OrdinalIgnoreCase);if(!match)continue;if(window!=null)throw new InvalidOperationException("Unique window guard");window=w;}catch(ElementNotAvailableException){continue;}}if(window==null)throw new InvalidOperationException("Owned window absent");
  if(source){bool url=false;foreach(AutomationElement e in window.FindAll(TreeScope.Descendants,Condition.TrueCondition)){object v;if(e.Current.ControlType==ControlType.Edit&&e.TryGetCurrentPattern(ValuePattern.Pattern,out v)){string value=((ValuePattern)v).Current.Value;if(System.Text.RegularExpressions.Regex.IsMatch(value,@"^(http://)?10\.211\.55\.2:8768/connection-pageintegrationresults-actual\.html\?os=windows&recording=[0-9a-f]{32}(&resume=(after-data|english))?$"))url=true;}}if(!url)throw new InvalidOperationException("Exact owned source URL required");}return window;

 }
 static void RunAware(string path,bool source,string target,string mode,string expectedID,string expectedName){
  var temp=System.IO.Path.GetFullPath(Environment.GetEnvironmentVariable("TEMP"));var actual=System.IO.Path.GetFullPath(path);if(!actual.StartsWith(temp+System.IO.Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)||!System.Text.RegularExpressions.Regex.IsMatch(actual.Substring(temp.Length+1),@"^DBMV-Isolated-connection-pageintegration-[0-9a-f]{32}\\app\\ReplicaProbe\.exe$"))throw new InvalidOperationException("Fixed runtime guard");
  if(target!="current"&&target!="sample"&&target!="filter:unknown"&&target!="language"&&target!="detail:data"&&target!="detail:trial"&&target!="research"&&target!="save"&&target!="back")throw new InvalidOperationException("Fixed parent target guard");if(mode!="click"&&mode!="space"&&mode!="escape"&&mode!="next"&&mode!="zero"&&mode!="filter-offset"&&mode!="research-offset"&&mode!="record")throw new InvalidOperationException("Fixed parent operation guard");
  LastStage="window";AutomationElement window=Window(path,source);
  AutomationElement c=null;
  if(target!="current"){
   if(string.IsNullOrWhiteSpace(source||string.IsNullOrEmpty(expectedID)?expectedName:expectedID))throw new InvalidOperationException("Fresh expected identity required");
   LastStage="target-lookup";foreach(AutomationElement candidate in window.FindAll(TreeScope.Descendants,Condition.TrueCondition)){
    if(candidate.Current.ControlType!=ControlType.Button)continue;bool match=source?System.Text.RegularExpressions.Regex.Replace(candidate.Current.Name,@"\s+"," ").Trim()==System.Text.RegularExpressions.Regex.Replace(expectedName,@"\s+"," ").Trim():string.IsNullOrEmpty(expectedID)?System.Text.RegularExpressions.Regex.Replace(candidate.Current.Name,@"\s+"," ").Trim()==System.Text.RegularExpressions.Regex.Replace(expectedName,@"\s+"," ").Trim():candidate.Current.AutomationId==expectedID;
    if(!match)continue;if(c!=null)throw new InvalidOperationException("Unique fresh target required");c=candidate;
   }
   if(c==null||!c.Current.IsEnabled)throw new InvalidOperationException("Enabled fresh source/native parent target guard");
  }
  LastStage="foreground";SetForegroundWindow(new IntPtr(window.Current.NativeWindowHandle));System.Threading.Thread.Sleep(100);if(GetForegroundWindow().ToInt64()!=window.Current.NativeWindowHandle)throw new InvalidOperationException("Foreground guard");
  if(mode!="click"){
   ushort code=mode=="space"?(ushort)32:mode=="escape"?(ushort)27:mode=="next"?(ushort)119:mode=="zero"?(ushort)116:mode=="filter-offset"?(ushort)118:mode=="research-offset"?(ushort)117:(ushort)123;
   var focus=AutomationElement.FocusedElement;if(focus==null||focus.Current.ProcessId!=window.Current.ProcessId)throw new InvalidOperationException("Owned existing focus guard");
   if(mode=="space"&&(c==null||focus.Current.AutomationId!=c.Current.AutomationId||focus.Current.Name!=c.Current.Name))throw new InvalidOperationException("Space needs existing target focus, no forced focus");
   Key(code);System.Threading.Thread.Sleep(400);return;
  }
  LastStage="target-frame";var b=c.Current.BoundingRectangle;var frame=window.Current.BoundingRectangle;if(!frame.Contains(b)||b.Width<40||b.Width>3000||b.Height<40||b.Height>400||c.Current.IsOffscreen)throw new InvalidOperationException("Visible parent button/frame guard");
  int x=(int)Math.Round(b.Left+b.Width/2),y=(int)Math.Round(b.Top+b.Height/2);POINT previous;if(!GetPhysicalCursorPos(out previous))throw new InvalidOperationException("Physical pointer guard");bool down=false;
  try{
   LastStage="pointer-move";Move(x,y);System.Threading.Thread.Sleep(150);if(GetForegroundWindow().ToInt64()!=window.Current.NativeWindowHandle)throw new InvalidOperationException("Foreground changed");POINT physical;if(!GetPhysicalCursorPos(out physical)||Math.Abs(physical.x-x)>1||Math.Abs(physical.y-y)>1)throw new InvalidOperationException("Fresh physical pointer position guard");
   LastStage="window-from-point";uint hitPid;var hit=WindowFromPoint(physical);var root=GetAncestor(hit,2);GetWindowThreadProcessId(root,out hitPid);var title=new System.Text.StringBuilder(512);GetWindowText(root,title,title.Capacity);var freshPath=System.Diagnostics.Process.GetProcessById((int)hitPid).MainModule.FileName;var fresh=c.Current.BoundingRectangle;var freshName=c.Current.Name;var freshId=c.Current.AutomationId;
   if(hit==IntPtr.Zero||root.ToInt64()!=window.Current.NativeWindowHandle||hitPid!=window.Current.ProcessId||!fresh.Contains(new System.Windows.Point(physical.x,physical.y))||!c.Current.IsEnabled||c.Current.IsOffscreen||(source?!title.ToString().StartsWith("Results integration actual · original isolation",StringComparison.Ordinal)||!freshPath.EndsWith(@"Microsoft\Edge\Application\msedge.exe",StringComparison.OrdinalIgnoreCase):title.ToString()!="Replica PageIntegration application verification"||!string.Equals(freshPath,path,StringComparison.OrdinalIgnoreCase))||(!source&&!string.IsNullOrEmpty(expectedID)&&freshId!=expectedID)||System.Text.RegularExpressions.Regex.Replace(freshName,@"\s+"," ").Trim()!=System.Text.RegularExpressions.Regex.Replace(expectedName,@"\s+"," ").Trim())throw new InvalidOperationException("Exact owned Win32 root/fresh target hit guard");
   if(TransportPath!=null)System.IO.File.AppendAllText(TransportPath,"guard=physicalcursor+WindowFromPoint/GA_ROOT exactHWND/PID/path/title+freshnamedvisibleenabledtarget requested="+x+","+y+" actual="+physical.x+","+physical.y+" root="+root+" pid="+hitPid+" path="+freshPath+" title="+title+" id="+freshId+" name="+freshName+"\n");
   if(source){LastStage="uia-from-point";var targetHit=AutomationElement.FromPoint(new System.Windows.Point(x,y));if(targetHit==null||targetHit.Current.ProcessId!=window.Current.ProcessId)throw new InvalidOperationException("Owned UIA point guard");}
   LastStage="mouse-down";Mouse(true);down=true;System.Threading.Thread.Sleep(40);if(GetForegroundWindow().ToInt64()!=window.Current.NativeWindowHandle)throw new InvalidOperationException("Held foreground lost");LastStage="mouse-up";Mouse(false);down=false;System.Threading.Thread.Sleep(400);LastStage="completed";
  }finally{if(down)Mouse(false);if(GetForegroundWindow().ToInt64()==window.Current.NativeWindowHandle)Move(previous.x,previous.y);}
 }
